  "777-3": "platelets", "26515-7": "platelets", "6690-2": "wbc", "26464-8": "wbc", "718-7": "hemoglobin",
  "6873-4": "bhb", "53060-3": "bhb", "2744-1": "ph", "2746-6": "ph", "11558-4": "ph",
